"""Build a self-contained ten-slide deck from committed evidence."""
from __future__ import annotations
import base64, html, json, os
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
REPO=os.environ.get('REPO_URL','{{REPO_URL}}')
if REPO=='{{REPO_URL}}': raise SystemExit('Set REPO_URL before building slides')
data=json.loads((ROOT/'evidence/tokenomics.json').read_text())
def image(name):
 p=ROOT/'evidence/design'/name
 return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() if p.exists() else ''
def img(name):
 s=image(name)
 return f'<img src="{s}">' if s else '<div class="missing">Screenshot placeholder</div>'
plan=data['run_types'].get('plan',{}); ns=data['run_types'].get('next_steps',{})
slides=[
f'<section class="title"><small>SAATHI · UDAY ADDANKI</small><h1>Plan the lesson.<br>Check who learned.<br>Know what to do next.</h1><p>Teacher copilot for India’s primary classrooms · no student devices</p><a href="{html.escape(REPO)}">{html.escape(REPO)}</a></section>',
'<section><h2>The problem</h2><p>Primary teachers prepare for tomorrow while children learn at different levels. A score alone does not say what to reteach. Saathi closes the loop from a lesson plan to a paper check to the next action.</p><div class="big">37–43</div><p>Children per pilot classroom; the three classes contained 38, 37, and 43 children.</p></section>',
'<section><h2>What is new</h2><div class="loop"><b>PLAN</b><b>→ CHECK</b><b>→ NEXT STEPS</b></div><ul><li>No student devices</li><li>Diagnosis and groups computed by code</li><li>Differentiated next lesson, not just a score</li></ul></section>',
'<section><h2>How it works</h2><svg viewBox="0 0 900 260" role="img" aria-label="Six-agent Saathi loop"><g fill="#f4ba55" stroke="#fffdf7" stroke-width="3" font-family="Arial" text-anchor="middle"><rect x="15" y="90" width="125" height="60" rx="16"/><rect x="160" y="90" width="125" height="60" rx="16"/><rect x="305" y="90" width="125" height="60" rx="16"/><rect x="450" y="90" width="125" height="60" rx="16"/><rect x="595" y="90" width="125" height="60" rx="16"/><rect x="740" y="90" width="145" height="60" rx="16"/></g><g fill="#123f39" font-size="16" text-anchor="middle" font-family="Arial"><text x="77" y="125">Planner</text><text x="222" y="125">Check Builder</text><text x="367" y="125">Reader</text><text x="512" y="125">Reviewer</text><text x="657" y="125">Coach</text><text x="812" y="125">Resources</text></g><path d="M75 205 C250 255 650 255 820 205" fill="none" stroke="#f4ba55" stroke-width="5"/><text x="450" y="245" fill="#fffdf7" font-size="16" text-anchor="middle">code marking · diagnosis · budgets · number checks</text></svg><p>Six prompted agents are orchestrated by plain Python. Code handles marking, readiness maths, support-child selection, and arithmetic validation.</p></section>',
f'<section><h2>From Plan to Check</h2><div class="twocol">{img("plan-form-laptop-1280x800.png")}{img("check-laptop-1280x800.png")}</div></section>',
f'<section><h2>From results to action</h2><div class="twocol">{img("next-steps-laptop-1280x800.png")}{img("additional-resources-laptop-1280x800.png")}</div></section>',
f'<section><h2>Real trace: one full loop</h2><div class="big">46.6s</div><p>Plan · 5 sheets 10.9s · Next steps 29.4s · worksheet 6.7s</p><p>14 model calls · 14 tools · trace cost is recorded in evidence/run_trace.json. One planner revision and one Coach revision were recorded.</p></section>',
'<section><h2>Safety by design</h2><ul><li>401 without a session</li><li>404 for another teacher’s data</li><li>Lockout and daily budgets</li><li>Prompt and output safety checks</li></ul><div class="callout">No children’s names or real answer-sheet images are included here.</div></section>',
'<section><h2>Piloted with real data from three classrooms</h2><div class="big">3 · 118 · 590</div><table><tr><th>Class</th><th>Children</th><th>Average</th><th>Low / Mid / High</th></tr><tr><td>Grade 2 TS</td><td>38</td><td>29.5%</td><td>40 / 26.3 / 25%</td></tr><tr><td>Grade 4 NCERT</td><td>37</td><td>81.1%</td><td>51.1 / 80 / 97.6%</td></tr><tr><td>Grade 5 TS</td><td>43</td><td>62.8%</td><td>38.8 / 71.1 / 88.9%</td></tr></table><p>Four feedback entries; mean rating 3.75. Anurag: “a blessing for a beginner teacher.”</p></section>',
'<section><h2>What comes next</h2><p>Verify chapter coverage, expand misconception libraries, add offline capture, and run a comparison-class pilot.</p><p>Run locally from the README.</p><a href="'+html.escape(REPO)+'">'+html.escape(REPO)+'</a><p class="small">The report documents the measured trace, pilot caveats, and evidence boundaries.</p></section>']
css="""*{box-sizing:border-box}body{margin:0;background:#123f39;color:#fffdf7;font-family:Arial,sans-serif}.deck{height:100vh}.slide{display:none;min-height:100vh;padding:8vh 10vw}.slide.active{display:block}h1{font-size:clamp(38px,6vw,82px);line-height:1.03;margin:30px 0}h2{font-size:clamp(32px,5vw,62px);margin:0 0 35px;color:#f4ba55}p,li{font-size:clamp(18px,2.2vw,30px);line-height:1.35;max-width:900px}a{color:#f4ba55}.title{display:flex;flex-direction:column;justify-content:center}.title small{letter-spacing:.2em;color:#f4ba55}.big{font-size:clamp(65px,12vw,150px);font-weight:bold;color:#f4ba55}.loop,.flow{display:flex;gap:18px;flex-wrap:wrap;margin:40px 0}.loop b,.flow{background:#f4ba55;color:#123f39;padding:16px 22px;border-radius:20px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:25px}.twocol img{max-width:100%;max-height:55vh;border-radius:14px}.callout{border:2px solid #f4ba55;padding:20px;border-radius:14px}.small{font-size:14px}.missing{border:2px dashed #f4ba55;padding:70px;text-align:center}@media(max-width:700px){.twocol{grid-template-columns:1fr}}"""
OUT=ROOT/'slides.html'
slides_markup=''.join(slides)
fallback="""if(window.Reveal){Reveal.initialize({hash:true,slideNumber:true,progress:true,center:false,width:1280,height:720});}else{const ss=[...document.querySelectorAll('.slides>section')];let n=0;function show(){ss.forEach((s,i)=>s.classList.toggle('present',i===n));}document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='PageDown')n=Math.min(n+1,ss.length-1);if(e.key==='ArrowLeft'||e.key==='PageUp')n=Math.max(n-1,0);show();});show();}"""
OUT.write_text(f"<!doctype html><html><head><meta charset='utf-8'><title>Saathi slides</title><link rel='stylesheet' href='https://cdn.jsdelivr.net/npm/reveal.js@5.1.0/dist/reveal.css'><link rel='stylesheet' href='https://cdn.jsdelivr.net/npm/reveal.js@5.1.0/dist/theme/black.css'><style>{css}.reveal .slides section{{text-align:left}}.reveal .slides img{{max-height:55vh}}.slides>section{{display:none!important}}.slides>section.present{{display:block!important}}</style></head><body><div class='reveal'><div class='slides'>{slides_markup}</div></div><script src='https://cdn.jsdelivr.net/npm/reveal.js@5.1.0/dist/reveal.js'></script><script>{fallback}</script></body></html>")
print(OUT)
